BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE actor uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();row jsonb;old jsonb;link uuid;domain uuid;managed jsonb;before_count integer;
BEGIN
 INSERT INTO auth.users(id) VALUES(actor),(outsider);INSERT INTO public.user_roles VALUES(actor,'admin');
 BEGIN PERFORM public.redirect_manual_record(outsider,p_values=>'{"type":"PATH","source_path":"/old","target":"/events"}');RAISE EXCEPTION 'Non-owner wrote manual redirect';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 row:=public.redirect_manual_record(actor,p_values=>'{"type":"PATH","source_path":"/old-fixture","match_kind":"WILDCARD","target":"/events","status_code":307,"notes":"Keep notes","start_at":"2026-01-01T00:00:00Z","end_at":"2030-01-01T00:00:00Z","click_limit":9,"query_mode":"OVERRIDE","query_override":{"audience":"friends"},"utm_defaults":{"utm_source":"poster"}}');link:=(row->>'id')::uuid;
 IF row->>'notes'<>'Keep notes' OR row->>'click_limit'<>'9' OR row->>'match_kind'<>'WILDCARD' OR NOT(row->>'preserve_query')::boolean THEN RAISE EXCEPTION 'Manual fields lost';END IF;
 old:=row;
 row:=public.redirect_manual_record(actor,link,'{"notes":"Edited notes"}',(row->>'updated_at')::timestamptz);
 IF row->>'source_path'<>'/old-fixture' OR row->>'click_limit'<>'9' OR row->>'created_by'<>actor::text THEN RAISE EXCEPTION 'Partial owner save reset fields';END IF;
 BEGIN PERFORM public.redirect_manual_record(actor,link,'{"target":"/stale"}',(old->>'updated_at')::timestamptz);RAISE EXCEPTION 'Stale owner write accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 BEGIN PERFORM public.redirect_manual_record(actor,link,'{"click_count":0}',(row->>'updated_at')::timestamptz);RAISE EXCEPTION 'Readonly counter accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 old:=public.redirect_domain_resource('create',actor,p_values=>'{"hostname":"manual.example.com"}');domain:=(old->>'id')::uuid;
 UPDATE public.redirect_domains SET ownership_state='verified',verified_at=now(),verified_until=now()+interval '1 day',provider_id=gen_random_uuid()::text WHERE id=domain;
 INSERT INTO public.redirect_domain_jobs(domain_id,zone_id,cname_target,requested_by,state,provider_status,ssl_status,checked_at) VALUES(domain,repeat('a',32),'links.queer.guide',actor,'ready','active','active',now());
 PERFORM public.record_redirect_domain_route('manual.example.com');
 PERFORM public.redirect_management_mutate('[{"operation":"create","data":{"slug":"manual-same","target":"/builtin"}}]');
 row:=public.redirect_manual_record(actor,link,jsonb_build_object('type','SHORT','slug','manual-same','domain_id',domain),(row->>'updated_at')::timestamptz);
 IF row->>'domain_hostname'<>'manual.example.com' OR row->>'source_path' IS NOT NULL OR row->>'match_kind'<>'EXACT' OR row->>'notes'<>'Edited notes' THEN RAISE EXCEPTION 'Atomic PATH to branded SHORT conversion failed';END IF;
 INSERT INTO public.redirect_link_policies(redirect_id,policy) VALUES(link,'{"expires_at":"2030-01-01T00:00:00Z","track_conversions":true}');
 row:=public.redirect_manual_record(actor,link,'{"end_at":null}',(row->>'updated_at')::timestamptz);
 IF EXISTS(SELECT FROM public.redirect_link_policies WHERE redirect_id=link AND policy?'expires_at') OR NOT EXISTS(SELECT FROM public.redirect_link_policies WHERE redirect_id=link AND policy->>'track_conversions'='true') THEN RAISE EXCEPTION 'Manual expiry failed to synchronize policy';END IF;
 UPDATE public.redirect_domains SET disabled=true WHERE id=domain;
 row:=public.redirect_manual_record(actor,link,'{"target":"/repaired"}',(row->>'updated_at')::timestamptz);
 IF (row->>'domain_id')::uuid<>domain THEN RAISE EXCEPTION 'Unavailable binding could not be preserved';END IF;
 old:=row;
 BEGIN PERFORM public.redirect_manual_record(actor,link,'{"type":"PATH","source_path":"invalid"}',(row->>'updated_at')::timestamptz);RAISE EXCEPTION 'Invalid conversion accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 IF public.redirect_manual_record(actor,link)<>old THEN RAISE EXCEPTION 'Failed conversion partially changed row';END IF;
 row:=public.redirect_manual_record(actor,link,'{"type":"PATH","source_path":"/converted","query_mode":"DROP"}',(row->>'updated_at')::timestamptz);
 IF row->>'domain_id' IS NOT NULL OR row->>'domain_hostname' IS NOT NULL OR row->>'slug' IS NOT NULL OR (row->>'preserve_query')::boolean THEN RAISE EXCEPTION 'PATH conversion retained short namespace';END IF;
 BEGIN PERFORM public.redirect_manual_record(actor,link,jsonb_build_object('type','SHORT','slug','manual-same','domain_id',domain),(row->>'updated_at')::timestamptz);RAISE EXCEPTION 'Unavailable domain rebound';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 IF public.redirect_manual_record(actor,link)->>'type'<>'PATH' THEN RAISE EXCEPTION 'Readiness failure changed type';END IF;
 managed:=public.redirect_management_mutate('[{"operation":"create","data":{"slug":"schedule-fields","target":"/events","startsAt":"2026-01-01T00:00:00Z","expiresAt":"2030-01-01T00:00:00Z","clickLimit":5,"notes":"Scoped notes"}}]');
 IF managed#>>'{0,link,clickLimit}'<>'5' OR managed#>>'{0,link,notes}'<>'Scoped notes' OR managed#>>'{0,link,startsAt}' IS NULL THEN RAISE EXCEPTION 'Managed full fields lost';END IF;
 link:=(managed#>>'{0,link,id}')::uuid;
 BEGIN PERFORM public.redirect_management_mutate(jsonb_build_array(jsonb_build_object('operation','update','id',link,'data',jsonb_build_object('startsAt','2031-01-01T00:00:00Z'))));RAISE EXCEPTION 'Inverted saved schedule accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 IF has_function_privilege('authenticated','public.redirect_manual_record(uuid,uuid,jsonb,timestamptz)','EXECUTE') THEN RAISE EXCEPTION 'Manual RPC grant exposed';END IF;
END $$;
ROLLBACK;
